package com.mygo.music;

import android.app.*;
import android.content.*;
import android.media.*;
import android.media.session.*;
import android.net.Uri;
import android.os.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.zip.*;

/** Native player identity, actual elapsed audio, Activity recreation and framework media transport. */
final class BackgroundPlaybackChecks {
    private final Instrumentation test;private final Context context;
    BackgroundPlaybackChecks(Instrumentation test){this.test=test;context=test.getTargetContext();}
    private interface Condition {boolean valid()throws Exception;}
    private static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    private void await(Condition condition,String message)throws Exception{long until=SystemClock.elapsedRealtime()+12000;while(SystemClock.elapsedRealtime()<until){boolean[] ready={false};Exception[] error={null};test.runOnMainSync(()->{try{ready[0]=condition.valid();}catch(Exception failure){error[0]=failure;}});if(ready[0])return;SystemClock.sleep(50);}throw new AssertionError(message);}
    private PlaybackService service(MainActivity activity)throws Exception{java.lang.reflect.Field field=MainActivity.class.getDeclaredField("playbackService");field.setAccessible(true);PlaybackService[] value={null};await(()->{value[0]=(PlaybackService)field.get(activity);return value[0]!=null;},"Activity did not connect to the playback service");return value[0];}
    private MainActivity launch(){return (MainActivity)test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
    static byte[] wav(int milliseconds){byte[] bytes=new byte[44+16*milliseconds];java.nio.ByteBuffer data=java.nio.ByteBuffer.wrap(bytes).order(java.nio.ByteOrder.LITTLE_ENDIAN);try{data.put("RIFF".getBytes("US-ASCII")).putInt(bytes.length-8).put("WAVEfmt ".getBytes("US-ASCII")).putInt(16).putShort((short)1).putShort((short)1).putInt(8000).putInt(16000).putShort((short)2).putShort((short)16).put("data".getBytes("US-ASCII")).putInt(bytes.length-44);}catch(Exception failure){throw new RuntimeException(failure);}return bytes;}
    private File audio(String name,int duration)throws Exception{File file=new File(context.getCacheDir(),name);try(FileOutputStream out=new FileOutputStream(file)){out.write(wav(duration));}return file;}
    void run()throws Exception{localLifecycle();providerQueue();}
    private void localLifecycle()throws Exception{
        File first=audio("background-first.wav",6000),second=audio("background-second.wav",20000);MainActivity activity=launch(),restored=null;PlaybackService service=service(activity);MediaController controller=new MediaController(context,service.token());JSONArray queue=new JSONArray().put(new JSONObject().put("uri",Uri.fromFile(first)).put("title","Background A")).put(new JSONObject().put("uri",Uri.fromFile(second)).put("title","Background B"));
        try{test.runOnMainSync(()->{try{PlaybackService.startQueue(activity,queue,0,0,73,false,false,"high");}catch(Exception failure){throw new RuntimeException(failure);}});await(()->service.snapshot().playing&&service.snapshot().position>=300,"initial background fixture did not play");MediaPlayer[] original={null};int[] leaving={0};test.runOnMainSync(()->{original[0]=service.snapshot().player;leaving[0]=service.snapshot().position;activity.moveTaskToBack(true);});await(()->service.snapshot().position>=leaving[0]+800,"audio stopped when Activity moved to background");test.runOnMainSync(()->check(service.snapshot().player==original[0],"background transition created another player"));controller.getTransportControls().pause();await(()->!service.snapshot().playing,"media-session pause did not pause audio");int[] paused={0};test.runOnMainSync(()->paused[0]=service.snapshot().position);SystemClock.sleep(400);test.runOnMainSync(()->check(Math.abs(service.snapshot().position-paused[0])<120,"paused audio clock kept moving"));test.runOnMainSync(activity::finish);restored=launch();PlaybackService same=service(restored);check(same==service,"Activity recreation replaced the live playback service");java.lang.reflect.Field field=MainActivity.class.getDeclaredField("player");field.setAccessible(true);MainActivity reopened=restored;test.runOnMainSync(()->{try{check(field.get(reopened)==original[0],"Activity reloaded the audio after returning");check(!service.snapshot().playing,"returning to app forcibly resumed paused playback");check(Math.abs(service.snapshot().position-paused[0])<150,"Activity restored an old playback position");}catch(Exception failure){throw new RuntimeException(failure);}});
            controller.getTransportControls().seekTo(1800);await(()->Math.abs(service.snapshot().position-1800)<180,"media session seek did not reach actual player");controller.getTransportControls().play();await(()->service.snapshot().playing,"media session play failed");NotificationManager notifications=context.getSystemService(NotificationManager.class);boolean[] mediaNotification={false};test.runOnMainSync(()->{for(android.service.notification.StatusBarNotification notification:notifications.getActiveNotifications())if(notification.getId()==7&&notification.getNotification().extras.getParcelable(Notification.EXTRA_MEDIA_SESSION)!=null)mediaNotification[0]=true;});check(mediaNotification[0],"foreground notification missing the real media-session token");
            test.runOnMainSync(()->reopened.moveTaskToBack(true));controller.getTransportControls().skipToNext();await(()->service.snapshot().playing&&service.snapshot().title.equals("Background B"),"background next-track command failed");check(controller.getMetadata().getString(MediaMetadata.METADATA_KEY_TITLE).equals("Background B"),"media session metadata did not follow background track");controller.getTransportControls().skipToPrevious();await(()->service.snapshot().playing&&service.snapshot().title.equals("Background A"),"background previous-track command failed");controller.getTransportControls().seekTo(5600);await(()->service.snapshot().playing&&service.snapshot().title.equals("Background B"),"queue did not advance after actual audio completion");MediaPlayer[] beforeRepeat={null};test.runOnMainSync(()->{service.setModes(false,true);beforeRepeat[0]=service.snapshot().player;service.seek(19600);});await(()->service.snapshot().playing&&service.snapshot().title.equals("Background B")&&service.snapshot().player!=beforeRepeat[0]&&service.snapshot().position<1500,"background single-track repeat failed");
            java.lang.reflect.Field focus=PlaybackService.class.getDeclaredField("focusListener");focus.setAccessible(true);AudioManager.OnAudioFocusChangeListener listener=(AudioManager.OnAudioFocusChangeListener)focus.get(service);test.runOnMainSync(()->{service.pause();listener.onAudioFocusChange(AudioManager.AUDIOFOCUS_GAIN);check(!service.snapshot().playing,"focus gain resumed a user-paused track");service.resume();listener.onAudioFocusChange(AudioManager.AUDIOFOCUS_LOSS_TRANSIENT);check(!service.snapshot().playing,"transient focus loss did not pause");listener.onAudioFocusChange(AudioManager.AUDIOFOCUS_GAIN);check(service.snapshot().playing,"temporary focus loss did not restore requested playback");listener.onAudioFocusChange(AudioManager.AUDIOFOCUS_LOSS);listener.onAudioFocusChange(AudioManager.AUDIOFOCUS_GAIN);check(!service.snapshot().playing,"permanent focus loss resumed unexpectedly");});java.lang.reflect.Field noisy=PlaybackService.class.getDeclaredField("noisy");noisy.setAccessible(true);test.runOnMainSync(()->{try{service.resume();((BroadcastReceiver)noisy.get(service)).onReceive(context,new Intent(AudioManager.ACTION_AUDIO_BECOMING_NOISY));check(!service.snapshot().playing,"headphone disconnect did not pause");service.stopPlayback();check(service.snapshot().player==null&&!service.snapshot().loading,"stop retained a native player");}catch(Exception failure){throw new RuntimeException(failure);}});
        }finally{test.runOnMainSync(()->{service.stopPlayback();activity.finish();});MainActivity last=restored;if(last!=null)test.runOnMainSync(last::finish);first.delete();second.delete();}
    }
    private void providerQueue()throws Exception{
        String id="background-provider-fixture";boolean previousCache=context.getSharedPreferences("library",0).getBoolean("auto_cache",true);context.getSharedPreferences("library",0).edit().putBoolean("auto_cache",false).putBoolean("plugin_network_"+id,true).commit();context.getSharedPreferences("plugin_data_"+id,0).edit().clear().commit();MainActivity activity=launch();PlaybackService service=service(activity);PluginManager manager=new PluginManager(activity);try(AudioServer server=new AudioServer()){
            String source="export function stream({id}){host.storage.set('streamCalls',(host.storage.get('streamCalls')||0)+1);return {url:'"+server.base()+"/'+id,headers:{'X-Source-Token':'fixture-token'}};}export function played({id}){host.storage.set('lastPlayed',id);}";ByteArrayOutputStream data=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(data)){zip.putNextEntry(new ZipEntry("plugin.json"));zip.write(("{\"id\":\""+id+"\",\"main\":\"index.js\",\"permissions\":{\"network\":[\"127.0.0.1\"]}}").getBytes("UTF-8"));zip.closeEntry();zip.putNextEntry(new ZipEntry("index.js"));zip.write(source.getBytes("UTF-8"));zip.closeEntry();}CountDownLatch done=new CountDownLatch(1);boolean[] installed={false};manager.installZipStream(new ByteArrayInputStream(data.toByteArray()),(ok,raw)->{installed[0]=ok;done.countDown();});check(done.await(30,TimeUnit.SECONDS)&&installed[0],"background provider fixture failed to install");JSONArray queue=new JSONArray().put(new JSONObject().put("uri","plugin://"+id+"?id=a").put("title","Provider A")).put(new JSONObject().put("uri","plugin://"+id+"?id=b").put("title","Provider B"));test.runOnMainSync(()->{try{PlaybackService.startQueue(activity,queue,0,0,80,false,false,"high");}catch(Exception failure){throw new RuntimeException(failure);}});await(()->service.snapshot().playing&&service.snapshot().title.equals("Provider A"),"provider A did not play through background service");test.runOnMainSync(()->activity.moveTaskToBack(true));await(()->service.snapshot().playing&&service.snapshot().title.equals("Provider B"),"background service did not resolve provider B after completion");check(server.aAuthenticated&&server.bAuthenticated,"source audio headers lost during background queue advancement");check(context.getSharedPreferences("plugin_data_"+id,0).getString("streamCalls","").equals("2"),"background transition reopened an already playing source");
        }finally{test.runOnMainSync(()->{service.stopPlayback();manager.close();activity.finish();});context.getSharedPreferences("library",0).edit().putBoolean("auto_cache",previousCache).remove("plugin_network_"+id).commit();PluginArchive.delete(new File(context.getFilesDir(),"plugins/"+id));}
    }
    private static final class AudioServer implements AutoCloseable {
        final ServerSocket server=new ServerSocket(0);volatile boolean aAuthenticated,bAuthenticated;
        AudioServer()throws Exception{Thread worker=new Thread(()->{while(!server.isClosed())try(Socket socket=server.accept()){socket.setSoTimeout(5000);BufferedReader input=new BufferedReader(new InputStreamReader(socket.getInputStream(),"US-ASCII"));String request=input.readLine(),line;boolean authenticated=false;while((line=input.readLine())!=null&&!line.isEmpty())if(line.equalsIgnoreCase("X-Source-Token: fixture-token"))authenticated=true;boolean first=request.contains(" /a ");if(first)aAuthenticated|=authenticated;else bAuthenticated|=authenticated;byte[] body=wav(first?1700:15000);socket.getOutputStream().write(("HTTP/1.1 200 OK\r\nContent-Type: audio/wav\r\nContent-Length: "+body.length+"\r\nConnection: close\r\n\r\n").getBytes("US-ASCII"));socket.getOutputStream().write(body);}catch(Exception ignored){}});worker.setDaemon(true);worker.start();}
        String base(){return "http://127.0.0.1:"+server.getLocalPort();}
        public void close()throws Exception{server.close();}
    }
}
